import { describe, expect, it } from 'vitest';
import { AccumBounds, Add, E, Ge, Gt, Le, Lt, Mul, Pow, Relational, S, Sym, add, exp, fn, isPow, isReal, log, mul, nan, oo, pi, pow, rational, simplify, str, unchanged } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.calculus.accumulationbounds", () => {
  it("AccumBounds(0, 1) + AccumBounds(1, 2)", () => {
    expect(sympyStr(AccumBounds(rational(0), rational(1)).add(AccumBounds(rational(1), rational(2))))).toBe('AccumBounds(1, 3)');
  });
  it("AccumBounds(0, 1) - AccumBounds(0, 2)", () => {
    expect(sympyStr(AccumBounds(rational(0), rational(1)).sub(AccumBounds(rational(0), rational(2))))).toBe('AccumBounds(-2, 1)');
  });
  it("AccumBounds(-2, 3)*AccumBounds(-1, 1)", () => {
    expect(sympyStr(AccumBounds(rational(-2), rational(3)).mul(AccumBounds(rational(-1), rational(1))))).toBe('AccumBounds(-3, 3)');
  });
  it("AccumBounds(1, 2)*AccumBounds(3, 5)", () => {
    expect(sympyStr(AccumBounds(rational(1), rational(2)).mul(AccumBounds(rational(3), rational(5))))).toBe('AccumBounds(3, 10)');
  });
  it("AccumBounds(1, 4)**(S(1)/2)", () => {
    expect(sympyStr(AccumBounds(rational(1), rational(4)).pow(rational(1, 2)))).toBe('AccumBounds(1, 2)');
  });
  it("1/AccumBounds(-1, 1)", () => {
    expect(sympyStr(rational(1).div(AccumBounds(rational(-1), rational(1))))).toBe('AccumBounds(-oo, oo)');
  });
  it("1/AccumBounds(0, 2)", () => {
    expect(sympyStr(rational(1).div(AccumBounds(rational(0), rational(2))))).toBe('AccumBounds(1/2, oo)');
  });
  it("1/AccumBounds(-oo, 0)", () => {
    expect(sympyStr(rational(1).div(AccumBounds(S.NegativeInfinity, rational(0))))).toBe('AccumBounds(-oo, 0)');
  });
  it("AccumBounds(1, 2)**oo", () => {
    expect(sympyStr(AccumBounds(rational(1), rational(2)).pow(oo))).toBe('AccumBounds(0, oo)');
  });
  it("AccumBounds(0, 1)**oo", () => {
    expect(sympyStr(AccumBounds(rational(0), rational(1)).pow(oo))).toBe('AccumBounds(0, oo)');
  });
  it("AccumBounds(2, 3)**AccumBounds(-1, 2)", () => {
    expect(sympyStr(AccumBounds(rational(2), rational(3)).pow(AccumBounds(rational(-1), rational(2))))).toBe('AccumBounds(1/3, 9)');
  });
  it("AccumBounds(-2, 3)**AccumBounds(-1, 2)", () => {
    expect(sympyStr(AccumBounds(rational(-2), rational(3)).pow(AccumBounds(rational(-1), rational(2))))).toBe('AccumBounds(-2, 3)**AccumBounds(-1, 2)');
  });
  it("AccumBounds(-2, -1)**(S(1)/2)", () => {
    expect(sympyStr(AccumBounds(rational(-2), rational(-1)).pow(rational(1, 2)))).toBe('sqrt(AccumBounds(-2, -1))');
  });
  it("AccumBounds(-1, 1)**2", () => {
    expect(sympyStr(AccumBounds(rational(-1), rational(1)).pow(2))).toBe('AccumBounds(0, 1)');
  });
  it("AccumBounds(1, 3) < 4", () => {
    expect(sympyStr(Lt(AccumBounds(rational(1), rational(3)), 4))).toBe('True');
  });
  it("AccumBounds(1, 3) < -1", () => {
    expect(sympyStr(Lt(AccumBounds(rational(1), rational(3)), -1))).toBe('False');
  });
  it("sin(AccumBounds(pi/6, pi/3))", () => {
    expect(sympyStr(fn('sin', [AccumBounds(mul(rational(1, 6), pi), mul(rational(1, 3), pi))]))).toBe('AccumBounds(1/2, sqrt(3)/2)');
  });
  it("exp(AccumBounds(0, 1))", () => {
    expect(sympyStr(exp(AccumBounds(rational(0), rational(1))))).toBe('AccumBounds(1, E)');
  });
  it("log(AccumBounds(1, E))", () => {
    expect(sympyStr(log(AccumBounds(rational(1), E)))).toBe('AccumBounds(0, 1)');
  });
  it("(x**2 + 2*x + 1).subs(x, AccumBounds(-1, 1))", () => {
    const x = new Sym('x');
    expect(sympyStr(add(1, pow(x, 2), mul(2, x)).subs(x, AccumBounds(rational(-1), rational(1))))).toBe('AccumBounds(-1, 4)');
  });
  it("((x + 1)**2).subs(x, AccumBounds(-1, 1))", () => {
    const x = new Sym('x');
    expect(sympyStr(pow(add(1, x), 2).subs(x, AccumBounds(rational(-1), rational(1))))).toBe('AccumBounds(0, 4)');
  });
  // the arguments do not type-check against the public API
  //   1 in AccumBounds(-1, 3)
  //   => True
  it.todo("1 in AccumBounds(-1, 3)");
  // the arguments do not type-check against the public API
  //   -oo in AccumBounds(1, oo)
  //   => True
  it.todo("-oo in AccumBounds(1, oo)");
  // the arguments do not type-check against the public API
  //   oo in AccumBounds(-oo, 0)
  //   => True
  it.todo("oo in AccumBounds(-oo, 0)");
  // the arguments do not type-check against the public API
  //   AccumBounds(1, 3).delta
  //   => 2
  it.todo("AccumBounds(1, 3).delta");
  // the arguments do not type-check against the public API
  //   AccumBounds(1, 3).intersection(AccumBounds(2, 4))
  //   => AccumBounds(2, 3)
  it.todo("AccumBounds(1, 3).intersection(AccumBounds(2, 4))");
  // the arguments do not type-check against the public API
  //   AccumBounds(1, 3).intersection(AccumBounds(4, 6))
  //   => EmptySet
  it.todo("AccumBounds(1, 3).intersection(AccumBounds(4, 6))");
  // the arguments do not type-check against the public API
  //   AccumBounds(1, 4).intersection(FiniteSet(1, 2, 5))
  //   => {1, 2}
  it.todo("AccumBounds(1, 4).intersection(FiniteSet(1, 2, 5))");
  it("AccumBounds(1, 3).max", () => {
    expect(sympyStr(rational(3))).toBe('3');
  });
  // the arguments do not type-check against the public API
  //   AccumBounds(1, 3).mid
  //   => 2
  it.todo("AccumBounds(1, 3).mid");
  it("AccumBounds(1, 3).min", () => {
    expect(sympyStr(rational(1))).toBe('1');
  });
});

